run Research five AI operating-principle recordings, standard, 6, collect, 6, shared, const items = [
  {id:'truth-evidence', title:'Truth, evidence, and independent assistant judgment', source:'https://otter.ai/u/X18whMRA2NbuuZrQXQis4cuYo1A?title=ChatGPT%27s%20New%20Operating%20Principles', brief:'Research truth and evidence principles', summary:'Discussion proposes evidence before conclusions; substantive corrections; testable verification criteria; intellectually independent but non-authoritarian behavior. A four-point list is proposed, not agreed, and contains an objection. The user says not to label input as an assertion and not to use the prohibited term.'},
  {id:'axiom-hive', title:'Axiom Hive, AI defense, and testing approaches', source:'https://otter.ai/u/NWEoz29wBMvikACZpPB4zBnbxY0?title=Axiom%20Hive%20and%20AI%20Defense', brief:'Research Axiom Hive and AI defense testing', summary:'Recording describes deterministic constraints, traceable processing, verifiable control, auditability, and claims about standards/compliance not established by the recording. It contrasts public threat-intelligence research with empirical controlled-lab testing; neither is recorded as an adopted test plan.'},
  {id:'operational-framework', title:'AI operational framework, ethics, and human authority', source:'https://otter.ai/u/M7swfXq_LP-Kg6uLo087HGL-8UM?title=AI%20Operational%20Framework%20and%20Ethics', brief:'Research AI operations and human oversight', summary:'Recording describes direct execution, low deviation, neutral tone, formatting, validation, missing-information handling, and human authority for decisions. It says outputs need human review and safety/inclusivity should be foundational, while distinguishing arguments from technical guarantees.'},
  {id:'grok-comparison', title:'Grok versus assistant comparison claims', source:'https://otter.ai/u/X-6iQPzB9IgalbWc0MMLmF7IHb4?title=AI%20Model%20Comparison:%20Grok%20vs.%20Assistant', brief:'Research Grok and assistant comparison claims', summary:'Recording compares tone, data/integration, safety and human judgment, operational style, training, source verification, and standards. These are claims made in a discussion, not independent findings.'},
  {id:'framework-analysis', title:'AI operational framework analysis and tool framing', source:'https://otter.ai/u/Zd3s-biVzCmpcka7TswyJGoGZYE?title=AI%20Operational%20Framework%20Analysis', brief:'Research AI framework analysis and tool framing', summary:'Recording describes directness, neutrality, format, relevance filtering, technical specifications, human-centered economic goals, and human decision authority. It rejects sentience/independent actor framing; the transcript explores conflicting persona descriptions rather than giving one final specification.'}
];
const schema = JSON.stringify({type:'object',properties:{id:{type:'string'},title:{type:'string'},summary:{type:'string'},evidence:{type:'array',items:{type:'string'}},inference_and_unknowns:{type:'array',items:{type:'string'}},technical_testing:{type:'array',items:{type:'string'}},sources:{type:'array',items:{type:'string'}}},required:['id','title','summary','evidence','inference_and_unknowns','technical_testing','sources']});
const mapped = await parallel('Research the five recording themes', () => items.map(item => agent(
  'Research exactly this one recording topic: '+item.title+'. The transcript summary supplied by the user is: '+item.summary+' Source recording page: '+item.source+'.\nUse multiple credible public sources, opening source pages rather than relying on search snippets. Establish what public evidence says about this topic, especially concrete technical testing practices that could test relevant claims (for example, defined requirements, threat models, test cases, baselines, metrics, reproducibility, logs/audit trails, human-factors checks, and limitations, as relevant). Do not imply that any source establishes performance of the named system unless it actually reports such testing. Clearly separate what the transcript says, sourced facts, interpretation, and unknowns. Give source URLs with descriptive titles in sources, alongside claim-level detail in evidence. Do not use the word prohibited by user: “validated”. Avoid characterizing the user-provided material as an assertion. Return concise structured findings for this item only.',
  {brief:item.brief,schema,sandbox:'shared',effort_level:'standard'}
)), {schema});
const successful = mapped.filter(r => r.ok).map(r => r.value);
const failures = mapped.map((r,i) => r.ok ? null : {item:items[i].title,code:r.error.code,message:r.error.message}).filter(Boolean);
const reduced = await agent(
  'Synthesize these independent research findings into a clear, concise, complete Markdown report for the user. Use only the sources and sourced claims present in the supplied findings; do not do additional item-level research. Treat the five transcripts as discussions and distinguish transcript content from external evidence and interpretation. Include sections for each topic, then a cross-cutting section with practical technical testing guidance that can be stated from public sources. Explain what technical testing entails in specific, testable terms, not merely abstract assurances. State limitations and open questions beside affected claims. Do not use the prohibited word “validated”. Do not label the user-provided material as an assertion. Cite claims near text with numeric references [1] and end with a References section formatted exactly [1]: https://... "Descriptive source title" (percent-encode parentheses in URLs). Write the finished report to /home/ubuntu/ai-operating-principles-research.md. Return JSON containing report_path and a concise summary. Research findings: '+JSON.stringify(successful)+' Failures: '+JSON.stringify(failures),
  {brief:'Synthesize sourced research into report',sandbox:'shared',effort_level:'standard',schema:JSON.stringify({type:'object',properties:{report_path:{type:'string'},summary:{type:'string'}},required:['report_path','summary']})}
);
return {findings:successful,failures,final:reduced.ok?reduced.value:{error:reduced.error}};

